100	
101	    case REMOTE_EVENT_AGENT_OUTPUT:
102	        /* Deliberately silent. A chunk lands every few tens of milliseconds and
103	         * splits mid-sentence, so logging one line per chunk filled the console
104	         * without saying anything the 'Agent replying' status line above has not
105	         * already said. The link accumulates them; the reply prints once, below. */
106	        break;
107	
108	    case REMOTE_EVENT_TURN_TRANSCRIPT:
109	        /* One call for the whole reply, not one per line. nx_vsyslog stamps its
110	         * prefix once per call, so printing line by line turned a reply into a
