45	lv_result_t lv_async_call(lv_async_cb_t async_xcb, void * user_data)
46	{
47	    /*Allocate an info structure*/
48	    lv_async_info_t * info = lv_malloc(sizeof(lv_async_info_t));
49	
50	    if(info == NULL)
51	        return LV_RESULT_INVALID;
52	
53	    /*Create a new timer*/
54	    lv_timer_t * timer = lv_timer_create(lv_async_timer_cb, 0, info);
55	
56	    if(timer == NULL) {
57	        lv_free(info);
58	        return LV_RESULT_INVALID;
59	    }
60	
61	    info->cb = async_xcb;
62	    info->user_data = user_data;
63	
64	    lv_timer_set_repeat_count(timer, 1);
65	    return LV_RESULT_OK;
66	}
